    END IF;
    SELECT id INTO v_branch_id
    FROM public.engineering_branches
    WHERE name = 'Civil Engineering'
    LIMIT 1;

    IF v_branch_id IS NULL THEN
        INSERT INTO public.engineering_branches (name, code, description, is_active)
        VALUES (
            'Civil Engineering',
            CASE WHEN EXISTS (SELECT 1 FROM public.engineering_branches WHERE code = 'CE')
                 THEN 'CE-' || upper(substr(replace(gen_random_uuid()::TEXT, '-', ''), 1, 8))
                 ELSE 'CE' END,
            'Civil engineering branch',
            TRUE
        )
        RETURNING id INTO v_branch_id;
    END IF;

    INSERT INTO public.subjects (branch_id, name, code, description, display_order, is_active)
    VALUES (
        v_branch_id,
        'Civil Engineering',
        CASE WHEN EXISTS (SELECT 1 FROM public.subjects WHERE code = 'CE')
             THEN 'CE-' || upper(substr(replace(gen_random_uuid()::TEXT, '-', ''), 1, 8))
             ELSE 'CE' END,
        'Civil engineering subjects and competitive exam practice',
        0,
        TRUE
    )
    ON CONFLICT (branch_id, name) DO NOTHING;

    SELECT id INTO v_subject_id
    FROM public.subjects
    WHERE branch_id = v_branch_id AND name = 'Civil Engineering'
    LIMIT 1;

    IF v_subject_id IS NULL THEN
        RAISE EXCEPTION 'Could not create or find Civil Engineering subject';
    END IF;


    SELECT id INTO v_test_id FROM public.mock_tests
    WHERE title = 'TGPSC AEE Civil Exam' LIMIT 1;

    IF v_test_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.mock_questions existing
        LEFT JOIN jsonb_to_recordset(v_seed) AS q(
            display_order INT, question_text TEXT, options JSONB, correct_answer TEXT
        ) ON q.display_order = existing.display_order
        WHERE existing.mock_test_id = v_test_id
          AND (q.display_order IS NULL
               OR existing.question_text IS DISTINCT FROM q.question_text
               OR existing.question_type IS DISTINCT FROM 'mcq'
               OR existing.options IS DISTINCT FROM q.options
               OR existing.correct_answer IS DISTINCT FROM q.correct_answer
               OR existing.marks IS DISTINCT FROM 2
               OR existing.negative_marks IS DISTINCT FROM 0)
    ) THEN
        RAISE EXCEPTION 'Existing TGPSC AEE Civil questions differ from this seed; refusing to overwrite answers or attempt history';
    END IF;

    IF v_test_id IS NULL THEN
        INSERT INTO public.mock_tests (
            title, description, exam_type, subject_id, duration_minutes,
            total_marks, passing_marks, is_published
        ) VALUES (
            'TGPSC AEE Civil Exam', 'Unofficial practice version based on the uploaded TSPSC AEE Civil Paper II, 22 January 2023 (paper code 22122). 150 questions: 108 transcribed with notation/wording normalization and 42 explicitly labeled concept adaptations or corrections. Answers are independently derived, not an official answer key. Practice scoring: +2 correct, 0 wrong or unanswered; 150-minute duration. The 150-mark practice benchmark is not an official qualifying cutoff.',
            'OTHER', v_subject_id, 150, 300, 150, TRUE
        ) RETURNING id INTO v_test_id;
    ELSE
        UPDATE public.mock_tests SET
            description = 'Unofficial practice version based on the uploaded TSPSC AEE Civil Paper II, 22 January 2023 (paper code 22122). 150 questions: 108 transcribed with notation/wording normalization and 42 explicitly labeled concept adaptations or corrections. Answers are independently derived, not an official answer key. Practice scoring: +2 correct, 0 wrong or unanswered; 150-minute duration. The 150-mark practice benchmark is not an official qualifying cutoff.',
            exam_type = 'OTHER', subject_id = v_subject_id,
            duration_minutes = 150, total_marks = 300, passing_marks = 150,
            is_published = TRUE
        WHERE id = v_test_id;
    END IF;

    INSERT INTO public.mock_questions (
        mock_test_id, question_text, question_type, options, correct_answer,
        marks, negative_marks, display_order
    )
    SELECT v_test_id, q.question_text, 'mcq', q.options, q.correct_answer,
           2, 0, q.display_order
    FROM jsonb_to_recordset(v_seed) AS q(
        display_order INT, question_text TEXT, options JSONB, correct_answer TEXT
    )
    WHERE NOT EXISTS (
        SELECT 1 FROM public.mock_questions existing
        WHERE existing.mock_test_id = v_test_id AND existing.display_order = q.display_order
    );

    SELECT count(*) INTO v_question_count FROM public.mock_questions
    WHERE mock_test_id = v_test_id;
    IF v_question_count <> 150 OR (
        SELECT count(DISTINCT display_order) FROM public.mock_questions WHERE mock_test_id = v_test_id
    ) <> 150 THEN
        RAISE EXCEPTION 'Expected 150 uniquely ordered questions, found %', v_question_count;
    END IF;
    RAISE NOTICE 'TGPSC AEE Civil Exam ready: 150 questions, 300 marks, unofficial practice key.';
END;
$seed$;
